  els.roCount.textContent = String(connectedCount()).padStart(2, '0');
  const n = state.memory?.length || 0;
  els.roMemory.textContent = n === 1 ? '1 Eintrag' : `${n} Einträge`;
  $('sideMemCount').textContent = String(n);
