/* Jarvis – scharfer HUD-Stil: feine 1px-Linien, keine Weichzeichner */
:root {
  --bg: #03070c;
  --panel: #07131d;
  --panel-2: #0a1a27;
  --line: #12324a;
  --line-2: #1d5272;
  --text: #d8f3ff;
  --muted: #6c93a8;
  --dim: #3d5d70;
  --accent: #48dcff;
  --accent-bg: rgba(72, 220, 255, .08);
  --warm: #ffb040;
  --ok: #3fe39b;
  --bad: #ff5c5c;
  --hud: "Bahnschrift", "DIN Alternate", "Segoe UI", system-ui, sans-serif;
  --mono: "Cascadia Mono", Consolas, "SF Mono", monospace;
  font-family: "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}
* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body { background: var(--bg); color: var(--text); display: flex; flex-direction: column; overflow: hidden; font-size: 14px; }
.shell { flex: 1; min-height: 0; display: flex; }
.content { flex: 1; min-width: 0; min-height: 0; display: flex; flex-direction: column; }
svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: square; stroke-linejoin: miter; }
button { font: inherit; color: inherit; cursor: pointer; border: 0; background: none; }
.hidden { display: none !important; }
.grow { flex: 1; }
.grid-bg { position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background: linear-gradient(#0a1824 1px, transparent 1px) 0 0 / 40px 40px, linear-gradient(90deg, #0a1824 1px, transparent 1px) 0 0 / 40px 40px; opacity: .55; }
body > *:not(.grid-bg):not(.settings):not(.scrim):not(.toast) { position: relative; z-index: 1; }

/* ---------- Kopfzeile ---------- */
.topbar { display: flex; align-items: center; justify-content: space-between; padding: 10px 16px 0 20px; flex: none; }
.brand { display: flex; align-items: center; gap: 10px; font-family: var(--hud); }
.brand-name { font-size: 13px; letter-spacing: .5em; color: var(--text); }
.brand-ver { font-family: var(--mono); font-size: 10px; color: var(--dim); }
.top-actions { display: flex; gap: 4px; }
.top-btn { width: 36px; height: 36px; display: grid; place-items: center; color: var(--muted); border: 1px solid transparent; }
.top-btn:hover { color: var(--accent); border-color: var(--line-2); background: var(--accent-bg); }
#speakToggle.off { color: var(--dim); } #speakToggle.off .wave { opacity: 0; }

/* ---------- Bühne: Kreis in der Mitte, Anzeigen links/rechts ---------- */
.stage { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 24px; padding: 0 24px; flex: none; }
.core-wrap { width: clamp(180px, 38vh, 380px); height: clamp(180px, 38vh, 380px); }
#core { width: 100%; height: 100%; display: block; }
.gauges { margin: 0; display: flex; flex-direction: column; gap: 10px; }
.gauges.left { align-items: flex-end; text-align: right; }
.gauge { position: relative; min-width: 150px; max-width: 220px; padding: 6px 10px; border: 1px solid var(--line); background: rgba(7, 19, 29, .85); }
.gauges.left .gauge { border-right: 2px solid var(--accent); }
.gauges.right .gauge { border-left: 2px solid var(--accent); }
.gauges.left .gauge::after, .gauges.right .gauge::after { content: ""; position: absolute; top: 50%; width: 16px; border-top: 1px solid var(--line-2); }
.gauges.left .gauge::after { right: -18px; } .gauges.right .gauge::after { left: -18px; }
.gauge dt { font-family: var(--hud); font-size: 9px; letter-spacing: .22em; text-transform: uppercase; color: var(--muted); }
.gauge dd { margin: 2px 0 0; font-family: var(--mono); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gauge.click { cursor: pointer; } .gauge.click:hover { border-color: var(--line-2); background: var(--accent-bg); }
.status { margin: 2px 0 6px; text-align: center; font-family: var(--hud); font-size: 11px; letter-spacing: .3em; color: var(--accent); display: flex; justify-content: center; align-items: center; gap: 8px; flex: none; }
.status .dot { width: 6px; height: 6px; background: currentColor; animation: blink 1.6s steps(2) infinite; }
.status.listening { color: var(--warm); } .status.error { color: var(--bad); }
@keyframes blink { 50% { opacity: .25; } }

.update-banner { align-self: center; display: flex; align-items: center; gap: 12px; padding: 6px 8px 6px 12px; border: 1px solid var(--ok); color: var(--ok); font-size: 12px; margin-bottom: 6px; flex: none; }

/* ---------- Chat (klein, unter dem Kreis) ---------- */
main { flex: 1; min-height: 0; overflow-y: auto; padding: 6px 24px 8px; border-top: 1px solid var(--line); }
.welcome .chips { display: none; }
.welcome { display: flex; flex-direction: column; align-items: center; text-align: center; padding-top: 14px; }
.welcome p { margin: 0 0 12px; color: var(--muted); font-size: 13px; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; max-width: 680px; }
.chip { border: 1px solid var(--line); background: var(--panel); padding: 6px 12px; font-size: 12px; }
.chip:hover { border-color: var(--accent); color: var(--accent); }
.chip .sym { color: var(--accent); margin-right: 6px; }

#messages { max-width: 760px; margin: 0 auto; display: flex; flex-direction: column; gap: 10px; padding-top: 10px; }
.msg { max-width: 88%; padding: 9px 12px; line-height: 1.55; font-size: 13.5px; word-wrap: break-word; animation: rise .18s ease-out; }
@keyframes rise { from { opacity: 0; transform: translateY(4px); } }
.msg .who { display: block; font-family: var(--hud); font-size: 9px; letter-spacing: .25em; margin-bottom: 3px; color: var(--muted); }
.msg.user { align-self: flex-end; background: #0b2234; border: 1px solid var(--line-2); }
.msg.user .who { text-align: right; }
.msg.assistant { align-self: flex-start; background: var(--panel); border: 1px solid var(--line); border-left: 2px solid var(--accent); }
.msg.assistant .who { color: var(--accent); }
.msg.error { align-self: center; border: 1px solid var(--bad); color: #ffb8b8; background: #1a0808; white-space: pre-wrap; font-size: 13px; }
.body p { margin: 0 0 .55em; } .body p:last-child { margin-bottom: 0; }
.body ul, .body ol { margin: .2em 0 .55em; padding-left: 1.25em; } .body li::marker { color: var(--accent); }
.msg code { background: #020509; border: 1px solid var(--line); padding: 0 4px; font-family: var(--mono); font-size: .92em; }
.msg pre { background: #020509; border: 1px solid var(--line); padding: 8px 10px; overflow-x: auto; font-family: var(--mono); font-size: 12.5px; margin: .4em 0; }
.msg pre code { background: none; border: 0; padding: 0; }
.cursor { display: inline-block; width: 7px; height: 1em; background: var(--accent); vertical-align: -2px; margin-left: 2px; animation: blink .8s steps(2) infinite; }
.steps { display: flex; flex-direction: column; gap: 2px; font-family: var(--mono); font-size: 11px; color: var(--muted); }
.steps .warn { color: var(--warm); }
.steps:not(:empty) + .body:not(:empty) { margin-top: 6px; }
.meta { margin-top: 8px; padding-top: 6px; border-top: 1px solid var(--line); font-family: var(--mono); font-size: 10.5px; color: var(--dim); display: flex; gap: 12px; flex-wrap: wrap; align-items: center; }
.meta .fb { color: var(--warm); }
.meta button { font-family: var(--hud); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); padding: 0; }
.meta button:hover { color: var(--accent); }

/* ---------- Eingabe (schmal) ---------- */
.composer { position: relative; display: flex; gap: 6px; align-items: flex-end; padding: 4px 24px 12px; max-width: 700px; width: 100%; margin: 0 auto; flex: none; }
.field { flex: 1; border: 1px solid var(--line-2); background: #050d14; }
.field:focus-within { border-color: var(--accent); }
.field textarea { width: 100%; display: block; resize: none; height: 32px; max-height: 120px; background: none; border: 0; color: var(--text); padding: 6px 10px; font: inherit; font-size: 13px; line-height: 20px; outline: none; }
.field textarea::placeholder { color: var(--dim); }
.mic, .send { width: 34px; height: 34px; display: grid; place-items: center; flex: none; border: 1px solid var(--line-2); }
.mic svg, .send svg { width: 16px; height: 16px; }
.mic { color: var(--accent); background: #050d14; }
.mic:hover { border-color: var(--accent); background: var(--accent-bg); }
.mic.rec { background: var(--warm); border-color: var(--warm); color: #140a00; }
.send { background: var(--accent); border-color: var(--accent); color: #011018; }
.send:hover { background: #7ae6ff; }
.send .i-stop { display: none; }
.send.stop { background: var(--bad); border-color: var(--bad); }
.send.stop .i-send { display: none; } .send.stop .i-stop { display: block; fill: currentColor; }
.suggest { position: absolute; left: 64px; right: 64px; bottom: calc(100% - 6px); background: #050d14; border: 1px solid var(--line-2); z-index: 5; max-height: 240px; overflow-y: auto; }
.suggest button { display: flex; gap: 12px; align-items: baseline; width: 100%; text-align: left; padding: 8px 12px; font-size: 12.5px; border-bottom: 1px solid var(--line); }
.suggest button b { font-family: var(--mono); color: var(--accent); font-weight: 400; min-width: 100px; }
.suggest button span { color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.suggest button.on, .suggest button:hover { background: var(--accent-bg); }

/* ---------- Einstellungen (Vollbild-Panel) ---------- */
.settings { position: fixed; inset: 0; z-index: 20; display: grid; place-items: center; padding: 28px; opacity: 0; pointer-events: none; transition: opacity .15s; }
.settings.open { opacity: 1; pointer-events: auto; }
.scrim { position: fixed; inset: 0; background: rgba(1, 4, 8, .82); opacity: 0; pointer-events: none; transition: opacity .15s; z-index: 10; }
.scrim.open { opacity: 1; pointer-events: auto; }
.settings-frame { width: min(1000px, 100%); height: min(720px, 100%); display: grid; grid-template-columns: 220px 1fr; border: 1px solid var(--line-2); background: var(--bg); }
.settings-nav { border-right: 1px solid var(--line); padding: 18px 0; display: flex; flex-direction: column; background: #050d14; }
.nav-title { margin: 0 0 12px; padding: 0 20px; font-family: var(--hud); font-size: 10px; letter-spacing: .3em; text-transform: uppercase; color: var(--dim); }
.settings-nav button { display: flex; gap: 12px; align-items: center; text-align: left; padding: 11px 20px; font-size: 13px; color: var(--muted); border-left: 2px solid transparent; }
.settings-nav button span { font-family: var(--mono); font-size: 10px; color: var(--dim); }
.settings-nav button:hover { color: var(--text); background: var(--accent-bg); }
.settings-nav button.on { color: var(--accent); border-left-color: var(--accent); background: var(--accent-bg); }
.settings-nav button.on span { color: var(--accent); }
.settings-main { position: relative; overflow-y: auto; padding: 22px 28px 30px; }
.settings-main .close { position: absolute; top: 12px; right: 12px; }
.settings-main h2 { margin: 0 0 6px; font-family: var(--hud); font-weight: 400; font-size: 18px; letter-spacing: .08em; }
.settings-main h3 { margin: 22px 0 8px; font-family: var(--hud); font-weight: 400; font-size: 11px; letter-spacing: .25em; text-transform: uppercase; color: var(--accent); }
.settings code { font-family: var(--mono); font-size: 12px; color: var(--accent); background: var(--accent-bg); padding: 1px 5px; }
.muted { color: var(--muted); font-size: 13px; margin: 0 0 14px; line-height: 1.5; }
.muted.flush { margin: 0; }
.setting { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 14px 0; border-bottom: 1px solid var(--line); }
.setting b { font-weight: 600; font-size: 13.5px; }
.setting small { display: block; color: var(--muted); font-size: 12px; margin-top: 3px; line-height: 1.45; max-width: 520px; }
.setting select { flex: 0 0 220px; }
.wake-status { font-family: var(--mono); font-size: 11.5px; color: var(--muted); margin: 10px 0 0; padding: 8px 10px; border: 1px solid var(--line); background: #050d14; }
.wake-status.ok { color: var(--ok); border-color: #1b5a40; } .wake-status.err { color: var(--bad); border-color: #5a1b1b; }
.soon { display: inline-block; font-family: var(--hud); letter-spacing: .3em; font-size: 11px; color: var(--accent); border: 1px dashed var(--line-2); padding: 14px 20px; }
input[type=range] { accent-color: var(--accent); width: 220px; }

.prov { border: 1px solid var(--line); background: var(--panel); padding: 12px 14px; margin-bottom: 8px; }
.prov.on { border-left: 2px solid var(--ok); }
.prov-top { display: flex; align-items: center; gap: 10px; }
.prov-order { display: flex; flex-direction: column; }
.prov-order button { color: var(--muted); height: 16px; line-height: 0; }
.prov-order button:hover { color: var(--accent); }
.prov-order button:disabled { opacity: .2; cursor: default; }
.prov-order svg { width: 14px; height: 14px; }
.prov-name { flex: 1; min-width: 0; }
.prov-name b { font-weight: 600; font-size: 13.5px; }
.prov-name small { display: block; color: var(--muted); font-size: 12px; margin-top: 2px; }
.prov-name code { margin-left: 4px; }
.badge { font-family: var(--hud); font-size: 9.5px; letter-spacing: .14em; text-transform: uppercase; padding: 3px 7px; border: 1px solid var(--line); color: var(--muted); white-space: nowrap; }
.badge.ok { color: var(--ok); border-color: #1b5a40; }
.prov-body { margin-top: 10px; display: flex; flex-direction: column; gap: 8px; }
.row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.row.end { justify-content: flex-end; }
.row .link, .row .danger { margin-right: auto; }
.row.end .link, .row.end .danger { margin-right: 0; }
input[type=password], input[type=text], select, .settings textarea {
  background: #050d14; border: 1px solid var(--line-2); color: var(--text); padding: 8px 10px; font: inherit; font-size: 13px; outline: none; }
input:focus, select:focus, .settings textarea:focus { border-color: var(--accent); }
select option { background: #050d14; }
input[type=password], .prov select { flex: 1; min-width: 0; }
.settings textarea { width: 100%; resize: vertical; margin-bottom: 8px; }
.primary { background: var(--accent); color: #011018; padding: 8px 16px; font-weight: 600; font-size: 13px; border: 1px solid var(--accent); }
.primary:hover { background: #7ae6ff; }
.primary.small { padding: 4px 10px; font-size: 12px; }
.primary:disabled { opacity: .5; cursor: default; }
.ghost { border: 1px solid var(--line-2); padding: 7px 14px; font-size: 13px; color: var(--muted); }
.ghost:hover { color: var(--accent); border-color: var(--accent); }
.ghost.small { padding: 4px 10px; font-size: 12px; }
.link { color: var(--accent); font-size: 12px; text-decoration: underline; padding: 0; }
.danger { color: var(--bad); font-size: 12px; padding: 0; }
.switch { position: relative; width: 38px; height: 20px; flex: none; }
.switch input { opacity: 0; width: 0; height: 0; }
.switch span { position: absolute; inset: 0; border: 1px solid var(--line-2); background: #050d14; transition: .15s; cursor: pointer; }
.switch span::after { content: ""; position: absolute; width: 12px; height: 12px; top: 3px; left: 3px; background: var(--muted); transition: .15s; }
.switch input:checked + span { border-color: var(--ok); background: #0b2a1e; }
.switch input:checked + span::after { transform: translateX(18px); background: var(--ok); }
.log { background: #020509; border: 1px solid var(--line); padding: 10px; font-family: var(--mono); font-size: 11px; color: var(--muted); max-height: 260px; overflow: auto; white-space: pre-wrap; margin: 0; }

.pack .row.end { margin-top: 8px; gap: 12px; }
.pack-sym { width: 32px; height: 32px; flex: none; display: grid; place-items: center; font-size: 15px; color: var(--accent); border: 1px solid var(--line-2); background: #050d14; }
.err { color: var(--bad) !important; }
.pack-editor { display: flex; flex-direction: column; gap: 8px; margin: 12px 0 14px; padding: 12px; border: 1px solid var(--accent); background: var(--accent-bg); }
.pack-editor input[type=text] { flex: 1; min-width: 0; }
.pack-editor textarea { margin: 0 !important; }
#peCmd { flex: 0 0 140px !important; font-family: var(--mono); }
#packList { margin-top: 14px; }
#memInput { flex: 1; min-width: 0; }
.mem-list { list-style: none; margin: 12px 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.mem-list li { display: grid; grid-template-columns: 1fr auto; column-gap: 8px; align-items: center; padding: 8px 4px 8px 12px; border: 1px solid var(--line); border-left: 2px solid var(--accent); background: var(--panel); font-size: 13px; }
.mem-list li.muted { border-left-color: var(--line); display: block; }
.mem-list li small { grid-column: 1; color: var(--dim); font-size: 10.5px; font-family: var(--mono); margin-top: 2px; }
.mem-list li button { grid-column: 2; grid-row: 1 / 3; }
.icon-btn { width: 30px; height: 30px; display: grid; place-items: center; color: var(--muted); }
.icon-btn:hover { color: var(--bad); }

/* ---------- Tafeln & Widgets ---------- */
.tafel { overflow-x: auto; margin: .4em 0 .7em; border: 1px solid var(--line-2); }
.tafel table { border-collapse: collapse; width: 100%; font-size: 13px; }
.tafel th { font-family: var(--hud); font-weight: 400; font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: var(--accent); background: #081b29; text-align: left; padding: 7px 10px; border-bottom: 1px solid var(--line-2); white-space: nowrap; }
.tafel td { padding: 6px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
.tafel tr:last-child td { border-bottom: 0; }
.tafel .a-right { text-align: right; font-family: var(--mono); } .tafel .a-center { text-align: center; }
.widget { margin: .45em 0 .8em; padding: 10px 12px; border: 1px solid var(--line-2); background: #061420; }
.w-title { font-family: var(--hud); font-size: 10px; letter-spacing: .2em; text-transform: uppercase; color: var(--accent); margin-bottom: 8px; }
.w-loading { color: var(--muted); font-family: var(--mono); font-size: 11.5px; animation: blink 1.2s steps(2) infinite; }
.w-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 6px; }
.w-stat { padding: 7px 9px; background: #030a10; border: 1px solid var(--line); border-top: 2px solid var(--accent); }
.w-stat span { display: block; font-size: 10.5px; color: var(--muted); }
.w-stat b { display: block; font-family: var(--mono); font-size: 18px; font-weight: 400; margin-top: 2px; }
.w-check ul, .w-time ol { list-style: none; margin: 0; padding: 0; }
.w-check li { padding: 4px 0; border-bottom: 1px dashed var(--line); } .w-check li:last-child { border-bottom: 0; }
.w-check label { display: flex; gap: 10px; align-items: flex-start; cursor: pointer; }
.w-check input { appearance: none; width: 14px; height: 14px; flex: none; margin-top: 3px; border: 1px solid var(--accent); cursor: pointer; display: grid; place-items: center; }
.w-check input:checked { background: var(--accent); }
.w-check input:checked::after { content: ""; width: 7px; height: 3px; border: 2px solid #011018; border-top: 0; border-right: 0; transform: rotate(-45deg) translate(1px, -1px); }
.w-check input:checked + span { color: var(--muted); text-decoration: line-through; }
.w-bar { display: grid; grid-template-columns: minmax(80px, 28%) 1fr auto; gap: 10px; align-items: center; padding: 3px 0; font-size: 12.5px; }
.w-bl { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--muted); }
.w-track { height: 8px; border: 1px solid var(--line-2); background: #030a10; }
.w-track i { display: block; height: 100%; width: 0; background: var(--accent); transition: width .5s ease-out; }
.w-bv { font-family: var(--mono); font-size: 11.5px; min-width: 56px; text-align: right; }
.w-time li { display: grid; grid-template-columns: 58px 1fr; gap: 12px; padding: 5px 0; }
.w-time li + li { border-top: 1px dashed var(--line); }
.w-time time { font-family: var(--mono); color: var(--accent); font-size: 12.5px; }

.toast { position: fixed; left: 50%; bottom: 84px; transform: translate(-50%, 12px); background: #071520; border: 1px solid var(--accent); padding: 8px 14px; font-size: 12.5px; opacity: 0; transition: .2s; pointer-events: none; z-index: 30; max-width: 90%; }
.toast.show { opacity: 1; transform: translate(-50%, 0); }
::-webkit-scrollbar { width: 8px; } ::-webkit-scrollbar-thumb { background: var(--line-2); }

/* ---------- schmale Fenster ---------- */
@media (max-width: 860px) {
  .gauges { display: none; }
  .stage { grid-template-columns: 1fr; justify-items: center; }
  .settings { padding: 0; }
  .settings-frame { grid-template-columns: 1fr; grid-template-rows: auto 1fr; height: 100%; border: 0; }
  .settings-nav { flex-direction: row; overflow-x: auto; padding: 0; border-right: 0; border-bottom: 1px solid var(--line); }
  .nav-title { display: none; }
  .settings-nav button { white-space: nowrap; border-left: 0; border-bottom: 2px solid transparent; padding: 12px 14px; }
  .settings-nav button.on { border-bottom-color: var(--accent); }
  .settings-nav button span { display: none; }
  .setting { flex-wrap: wrap; } .setting select { flex: 1 1 100%; }
  main, .composer { padding-left: 14px; padding-right: 14px; }
}
@media (max-height: 640px) { .core-wrap { width: 160px; height: 160px; } }
.core-wrap { transition: width .3s ease, height .3s ease; }
body.chatting .core-wrap { width: clamp(150px, 26vh, 260px); height: clamp(150px, 26vh, 260px); }

/* ---------- Seitenleiste ---------- */
.side { width: 248px; flex: none; display: flex; flex-direction: column; border-right: 1px solid var(--line); background: rgba(5, 13, 20, .94); min-height: 0; }
body.side-off .side { display: none; }
.side-new { display: flex; align-items: center; gap: 8px; margin: 10px 12px 6px; padding: 8px 12px; border: 1px solid var(--line-2); color: var(--accent); font-size: 13px; }
.side-new:hover { background: var(--accent-bg); border-color: var(--accent); }
.side-title { padding: 12px 14px 4px; font-family: var(--hud); font-size: 9.5px; letter-spacing: .25em; text-transform: uppercase; color: var(--dim); }
.packs-title { cursor: pointer; border-top: 1px solid var(--line); margin-top: 6px; display: flex; justify-content: space-between; }
.packs-title:hover { color: var(--muted); }
.chat-list { flex: 1; min-height: 60px; overflow-y: auto; padding: 0 6px 6px; }
.chat-group { padding: 8px 8px 3px; font-family: var(--mono); font-size: 10px; color: var(--dim); }
.chat-item { position: relative; display: flex; align-items: center; gap: 8px; width: 100%; padding: 7px 8px; text-align: left; font-size: 13px; color: var(--muted); border-left: 2px solid transparent; cursor: pointer; }
.chat-item:hover { background: var(--accent-bg); color: var(--text); }
.chat-item.on { color: var(--accent); border-left-color: var(--accent); background: var(--accent-bg); }
.chat-item .t { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chat-item input { flex: 1; min-width: 0; padding: 2px 6px; font-size: 13px; }
.chat-item .dot { width: 6px; height: 6px; flex: none; background: var(--accent); }
.chat-item .dot.run { background: var(--warm); animation: blink 1s steps(2) infinite; }
.chat-item .x { display: none; width: 20px; height: 20px; place-items: center; color: var(--dim); flex: none; }
.chat-item .x svg { width: 12px; height: 12px; }
.chat-item:hover .x { display: grid; } .chat-item .x:hover { color: var(--bad); }
.side-packs { max-height: 30vh; overflow-y: auto; padding: 0 6px 6px; }
body.packs-off .side-packs { display: none; }
.side-pack { display: flex; gap: 8px; align-items: baseline; width: 100%; padding: 5px 8px; font-size: 12.5px; color: var(--muted); text-align: left; }
.side-pack:hover { color: var(--accent); background: var(--accent-bg); }
.side-pack .sym { color: var(--accent); width: 14px; text-align: center; flex: none; }
.side-pack code { margin-left: auto; font-family: var(--mono); font-size: 10.5px; color: var(--dim); }
.side-foot { border-top: 1px solid var(--line); padding: 6px; display: flex; flex-direction: column; }
.side-foot button { display: flex; align-items: center; gap: 8px; padding: 7px 8px; font-size: 12.5px; color: var(--muted); text-align: left; }
.side-foot button:hover { color: var(--accent); background: var(--accent-bg); }
.side-foot svg { width: 15px; height: 15px; }
.side-foot b { margin-left: auto; font-family: var(--mono); font-weight: 400; font-size: 11px; color: var(--dim); }

/* ---------- KI-Verwaltung ---------- */
.tempo h3, #providerList + h3 { margin-top: 18px; }
.prov .speed { font-family: var(--mono); font-size: 10.5px; color: var(--dim); white-space: nowrap; }
.catalog { display: flex; flex-wrap: wrap; gap: 6px; }
.catalog button { border: 1px solid var(--line-2); padding: 6px 12px; font-size: 12.5px; color: var(--muted); }
.catalog button:hover, .catalog button.on { color: var(--accent); border-color: var(--accent); background: var(--accent-bg); }
.add-form { margin-top: 12px; padding: 12px; border: 1px solid var(--accent); background: var(--accent-bg); display: flex; flex-direction: column; gap: 8px; }
.add-form input[type=text], .add-form input[type=password] { flex: 1; min-width: 0; }
@media (max-width: 860px) { .side { position: fixed; left: 0; top: 56px; bottom: 0; z-index: 8; width: 260px; } }

.side-search { position: relative; margin: 4px 12px 0; }
.side-search input { width: 100%; padding: 6px 26px 6px 10px; font-size: 12.5px; }
.side-search button { position: absolute; right: 4px; top: 50%; transform: translateY(-50%); width: 22px; height: 22px; color: var(--muted); font-size: 16px; line-height: 1; }
.side-search button:hover { color: var(--accent); }
.chat-item { flex-wrap: wrap; }
.chat-item .sn { flex: 0 0 100%; font-size: 11px; color: var(--dim); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.steps-list { padding-left: 1.2em; line-height: 1.6; } .steps-list li { margin-bottom: 4px; }
.pair-code { font-family: var(--mono); font-size: 26px; letter-spacing: .3em; color: var(--accent); border: 1px solid var(--accent); padding: 4px 14px; }

files.router.js:
// Jarvis Router: verteilt Anfragen an die verbundenen KIs.
// Wiederholt nur bei vorübergehenden Fehlern, wechselt danach zur nächsten KI.
// Bei Live-Antworten wird nur gewechselt, solange noch kein Wort angezeigt wurde.

const RETRYABLE_STATUS = new Set([408, 429, 500, 502, 503, 504, 529]);

class ProviderError extends Error {
  constructor(message, { status = null, retryAfterMs = null, network = false, timeout = false, streamed = false, modelGone = false, lost = false } = {}) {
    super(message);
    this.name = 'ProviderError';
    this.status = status;
    this.retryAfterMs = retryAfterMs;
    this.network = network;
    this.timeout = timeout;
    this.streamed = streamed; // es wurde schon Text angezeigt
    this.modelGone = modelGone; // Modell abgeschaltet / nicht gefunden
    this.lost = lost; // eine andere KI war schneller
  }
}

function isRetryable(err) {
  if (!(err instanceof ProviderError) || err.streamed || err.lost) return false;
  if (err.timeout || err.network) return true;
  return err.status != null && RETRYABLE_STATUS.has(err.status);
}

function parseRetryAfter(value, now = Date.now()) {
  if (value == null || value === '') return null;
  const secs = Number(value);
  if (Number.isFinite(secs)) return Math.max(0, secs * 1000);
  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - now);
  return null;
}

function backoffDelay(attempt, { baseMs = 800, maxMs = 15000, random = Math.random } = {}) {
  const exp = Math.min(maxMs, baseMs * 2 ** attempt);
  return Math.round(exp / 2 + random() * (exp / 2));
}

const defaultSleep = (ms) => new Promise((r) => setTimeout(r, ms));

// timeoutMs = Zeit bis zum ersten Lebenszeichen; jedes beat() startet die Uhr neu (für Live-Antworten)
async function callOnce(fn, timeoutMs) {
  const ctrl = new AbortController();
  let timer = setTimeout(() => ctrl.abort(), timeoutMs);
  const beat = () => { clearTimeout(timer); timer = setTimeout(() => ctrl.abort(), timeoutMs); };
  try {
    return await fn(ctrl.signal, beat);
  } catch (err) {
    if (err instanceof ProviderError && !ctrl.signal.aborted) throw err;
    if (ctrl.signal.aborted || err?.name === 'AbortError') {
      throw new ProviderError(`Zeitüberschreitung nach ${Math.round(timeoutMs / 1000)} s`, { timeout: true, streamed: !!err?.streamed });
    }
    throw new ProviderError(`Netzwerkfehler: ${err?.message || err}`, { network: true });
  } finally {
    clearTimeout(timer);
  }
}

async function callWithRetry(fn, { maxRetries = 2, timeoutMs = 60000, sleep = defaultSleep, random = Math.random, onRetry } = {}) {
  let attempt = 0;
  for (;;) {
    try {
      return await callOnce(fn, timeoutMs);
    } catch (err) {
      if (!isRetryable(err) || attempt >= maxRetries) throw err;
      const wait = err.retryAfterMs != null ? Math.min(err.retryAfterMs, 60000) : backoffDelay(attempt, { random });
      onRetry?.({ attempt: attempt + 1, waitMs: wait, error: err });
      await sleep(wait);
      attempt++;
    }
  }
}

/**
 * chain: [{ id, label, run: (signal, beat, ctx) => Promise<string>, repair?: (err) => Promise<boolean> }]
 * ctx.claim(): vor dem ersten angezeigten Text aufrufen – nur die KI, die zuerst "claimt", gewinnt;
 *   alle anderen laufenden KIs werden sofort abgebrochen. false = zu spät, Text verwerfen.
 * repair: darf z. B. ein abgeschaltetes Modell ersetzen; true = gleiche KI nochmal versuchen
 *
 * opts.parallel  Wie viele KIs gleichzeitig starten (1 = nacheinander)
 * opts.hedgeMs   Antwortet noch keine KI nach dieser Zeit, wird zusätzlich die nächste gestartet (0 = aus)
 * opts.maxActive Obergrenze gleichzeitig laufender Anfragen
 */
function runWithFallback(chain, opts = {}) {
  const { log = () => {}, onSwitch = () => {}, onLaunch = () => {}, parallel = 1, hedgeMs = 0, maxActive = 3 } = opts;
  if (!chain.length) return Promise.reject(new ProviderError('Keine KI verbunden. Öffne die Einstellungen und verbinde mindestens einen Anbieter.'));
  const failures = [];
  const active = new Set();
  let next = 0;
  let winner = null;
  let settled = false;
  let hedgeTimer = null;
  const losers = [];

  return new Promise((resolve, reject) => {
    const finish = (fn, value) => { if (settled) return; settled = true; clearTimeout(hedgeTimer); fn(value); };

    function claim(att) {
      if (winner && winner !== att) return false;
      if (!winner) {
        winner = att;
        clearTimeout(hedgeTimer);
        for (const other of active) if (other !== att) { other.lost = true; losers.push({ id: other.step.id, ms: Date.now() - other.startedAt }); other.ctrl.abort(); }
      }
      return true;
    }

    async function runAttempt(att) {
      const { step } = att;
      const wrapped = (signal, beat) => {
        if (att.lost) throw new ProviderError('Eine andere KI war schneller', { lost: true });
        return step.run(AbortSignal.any([signal, att.ctrl.signal]), beat, { claim: () => claim(att) });
      };
      let repaired = false;
      for (;;) {
        try {
          return await callWithRetry(wrapped, {
            ...opts,
            onRetry: ({ attempt, waitMs, error }) => log(`[${step.label}] Versuch ${attempt} in ${waitMs} ms – ${error.message}`),
          });
        } catch (err) {
          if (att.lost) throw new ProviderError('Eine andere KI war schneller', { lost: true });
          if (err.streamed) throw err; // schon Text angezeigt -> nicht doppelt antworten
          if (!repaired && err.modelGone && step.repair) {
            repaired = true;
            try {
              if (await step.repair(err)) { log(`[${step.label.split(' · ')[0]}] Modell veraltet – auf neues Modell umgestellt`); continue; }
            } catch { /* Reparatur fehlgeschlagen */ }
          }
          throw err;
        }
      }
    }

    function scheduleHedge() {
      clearTimeout(hedgeTimer);
      if (!(hedgeMs > 0) || winner || settled || next >= chain.length) return;
      hedgeTimer = setTimeout(() => {
        if (winner || settled || next >= chain.length) return;
        if (active.size < maxActive) launch('slow'); else scheduleHedge();
      }, hedgeMs);
    }

    function launch(reason) {
      const step = chain[next++];
      const att = { step, ctrl: new AbortController(), lost: false, startedAt: Date.now() };
      active.add(att);
      if (reason === 'failed' && failures.length) onSwitch(step, failures[failures.length - 1]);
      onLaunch(step, reason, failures[failures.length - 1]);
      runAttempt(att).then((text) => onDone(att, text), (err) => onFail(att, err));
      scheduleHedge();
    }

    function onDone(att, text) {
      if (settled || (winner && winner !== att)) return;
      claim(att);
      active.delete(att);
      log(failures.length ? `[${att.step.label}] hat übernommen` : `[${att.step.label}] hat geantwortet`);
      finish(resolve, { text, used: att.step, failures, losers, ms: Date.now() - att.startedAt });
    }

    function onFail(att, err) {
      active.delete(att);
      if (settled || err.lost || att.lost) return;
      if (err.streamed) {
        log(`[${att.step.label}] mitten in der Antwort abgebrochen: ${err.message}`);
        finish(reject, err);
        return;
      }
      log(`[${att.step.label}] fehlgeschlagen: ${err.message}`);
      failures.push({ id: att.step.id, label: att.step.label, error: err.message, ms: Date.now() - att.startedAt });
      if (winner) return;
      if (next < chain.length && (active.size === 0 || active.size < parallel)) { launch('failed'); return; }
      if (active.size === 0) {
        const summary = failures.map((f) => `• ${f.label}: ${f.error}`).join('\n');
        const e = new ProviderError(`Keine KI konnte antworten:\n${summary}`);
        e.failures = failures;
        finish(reject, e);
      }
    }

    const first = Math.max(1, Math.min(parallel, chain.length));
    for (let i = 0; i < first; i++) launch(i === 0 ? 'start' : 'parallel');
  });
}

module.exports = { ProviderError, isRetryable, parseRetryAfter, backoffDelay, callWithRetry, runWithFallback, RETRYABLE_STATUS };

files.speed.js:
// Misst, wie schnell jede KI das erste Wort liefert, und sortiert danach.
const DEFAULT_MS = 2500;

function record(old, ms, ok = true) {
  const sample = ok ? ms : Math.max(ms, 12000);
  if (!Number.isFinite(old)) return Math.round(sample);
  return Math.round(old * 0.6 + sample * 0.4);
}

/** Stabil: ähnlich schnelle KIs (gleiche 1,5-Sekunden-Stufe) behalten deine Reihenfolge. */
function sortBySpeed(ids, msOf) {
  return ids
    .map((id, i) => ({ id, i, bucket: Math.round((msOf(id) ?? DEFAULT_MS) / 1500) }))
    .sort((a, b) => a.bucket - b.bucket || a.i - b.i)
    .map((x) => x.id);
}

module.exports = { record, sortBySpeed, DEFAULT_MS };

files.updater.js:
// Selbst-Update über GitHub-Releases.
// Ein Release enthält die Datei "jarvis-app.json" = der komplette App-Code als Text.
// Der neue Code landet in %APPDATA%\Jarvis\app\<version>\ und wird beim Neustart geladen.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function cmpVersion(a, b) {
  const pa = String(a).replace(/^v/, '').split('.').map(Number);
  const pb = String(b).replace(/^v/, '').split('.').map(Number);
  for (let i = 0; i < 3; i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d) return Math.sign(d);
  }
  return 0;
}

const GH_HEADERS = { 'user-agent': 'Jarvis-Updater', accept: 'application/vnd.github+json' };

// Quelle 1: Datei release/version.json im Repo (einfach per Hochladen aktualisierbar)
async function fromRepoFile(repo, fetchImpl) {
  const base = `https://raw.githubusercontent.com/${repo}/main/release`;
  const res = await fetchImpl(`${base}/version.json?t=${Date.now()}`, { headers: { 'user-agent': 'Jarvis-Updater' }, signal: AbortSignal.timeout(10000) });
  if (!res.ok) return null;
  const j = await res.json();
  return j?.version ? { version: String(j.version).replace(/^v/, ''), notes: String(j.notes || ''), url: `${base}/jarvis-app.json?v=${j.version}` } : null;
}
// Quelle 2: GitHub-Release mit Asset jarvis-app.json
async function fromRelease(repo, fetchImpl) {
  const res = await fetchImpl(`https://api.github.com/repos/${repo}/releases/latest`, { headers: GH_HEADERS, signal: AbortSignal.timeout(10000) });
  if (!res.ok) return null;
  const rel = await res.json();
  const asset = (rel.assets || []).find((a) => a.name === 'jarvis-app.json');
  const version = String(rel.tag_name || '').replace(/^v/, '');
  return version && asset ? { version, notes: String(rel.body || ''), url: asset.browser_download_url } : null;
}

async function checkForUpdate({ repo, currentVersion, shellVersion, fetchImpl = fetch }) {
  const found = (await Promise.allSettled([fromRepoFile(repo, fetchImpl), fromRelease(repo, fetchImpl)]))
    .map((r) => (r.status === 'fulfilled' ? r.value : null)).filter(Boolean);
  if (!found.length) return { available: false, reason: 'Noch keine Updates veröffentlicht.' };
  const best = found.sort((a, b) => cmpVersion(b.version, a.version))[0];
  if (cmpVersion(best.version, currentVersion) <= 0) return { available: false, version: best.version, reason: 'Jarvis ist aktuell.' };
  return { available: true, version: best.version, notes: best.notes.slice(0, 2000), url: best.url, shellVersion };
}

function safeJoin(root, rel) {
  if (typeof rel !== 'string' || !rel || rel.includes('\0') || path.isAbsolute(rel) || /^[a-z]:/i.test(rel)) throw new Error(`Ungültiger Pfad: ${rel}`);
  const full = path.resolve(root, rel);
  if (!full.startsWith(path.resolve(root) + path.sep)) throw new Error(`Ungültiger Pfad: ${rel}`);
  return full;
}

/** Lädt und entpackt das Update. Gibt den Ordner zurück. */
async function downloadUpdate({ url, expectedVersion, appDir, shellVersion, fetchImpl = fetch }) {
  const res = await fetchImpl(url, { headers: { 'user-agent': 'Jarvis-Updater' }, redirect: 'follow', signal: AbortSignal.timeout(60000) });
  if (!res.ok) throw new Error(`Download fehlgeschlagen (${res.status})`);
  const raw = await res.text();
  const pkg = JSON.parse(raw);
  if (pkg.format !== 1 || !pkg.files || typeof pkg.files !== 'object') throw new Error('Update-Datei hat ein unbekanntes Format.');
  if (pkg.version !== expectedVersion) throw new Error('Versionsnummer passt nicht.');
  if (pkg.minShell && cmpVersion(shellVersion, pkg.minShell) < 0) {
    throw new Error(`Dieses Update braucht eine neue Grundinstallation (mind. ${pkg.minShell}). Bitte einmal neu herunterladen.`);
  }
  // Prüfsumme gegen Übertragungsfehler
  const hash = crypto.createHash('sha256').update(JSON.stringify(pkg.files)).digest('hex');
  if (pkg.sha256 && pkg.sha256 !== hash) throw new Error('Update-Datei ist beschädigt.');
  if (!pkg.files['main.js']) throw new Error('Update unvollständig.');

  const target = path.join(appDir, pkg.version);
  const tmp = `${target}.tmp-${Date.now()}`;
  for (const [rel, content] of Object.entries(pkg.files)) {
    const file = safeJoin(tmp, rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, typeof content === 'string' ? content : Buffer.from(content.base64, 'base64'));
  }
  fs.rmSync(target, { recursive: true, force: true });
  fs.renameSync(tmp, target);
  fs.writeFileSync(path.join(appDir, 'current.json'), JSON.stringify({ version: pkg.version, dir: target, tries: 0 }));
  return target;
}

module.exports = { cmpVersion, checkForUpdate, downloadUpdate, safeJoin };

files.wake.js:
// "Hey Jarvis": lokale Weckwort-Erkennung mit der eingebauten Windows-Spracherkennung (System.Speech).
// Läuft komplett offline auf dem PC. Erst nach dem Weckwort nimmt Jarvis deine Frage auf.
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const THRESHOLD = { low: 0.88, mid: 0.8, high: 0.7 };

// PowerShell-Skript: erkennt nur die Weckwort-Sätze; eine Diktat-Grammatik fängt alles andere ab (weniger Fehlalarme).
const SCRIPT = String.raw`
param([double]$Min = 0.8)
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
try {
  Add-Type -AssemblyName System.Speech
  $recs = [System.Speech.Recognition.SpeechRecognitionEngine]::InstalledRecognizers()
  if ($recs.Count -eq 0) { [Console]::Out.WriteLine('ERROR:Keine Windows-Spracherkennung installiert. Windows-Einstellungen > Zeit und Sprache > Sprache > Deutsch > Optionen > Spracherkennung hinzufügen.'); exit 2 }
  $info = $recs | Where-Object { $_.Culture.Name -eq 'de-DE' } | Select-Object -First 1
  if (-not $info) { $info = $recs | Where-Object { $_.Culture.Name -like 'de-*' } | Select-Object -First 1 }
  if (-not $info) { $info = $recs | Where-Object { $_.Culture.Name -like 'en-*' } | Select-Object -First 1 }
  if (-not $info) { $info = $recs[0] }
  $eng = New-Object System.Speech.Recognition.SpeechRecognitionEngine($info)
  $choices = New-Object System.Speech.Recognition.Choices
  $choices.Add([string[]]@('Hey Jarvis', 'Hei Jarvis', 'Hallo Jarvis', 'Okay Jarvis', 'Jarvis'))
  $gb = New-Object System.Speech.Recognition.GrammarBuilder($choices)
  $gb.Culture = $info.Culture
  $wake = New-Object System.Speech.Recognition.Grammar($gb)
  $wake.Name = 'wake'
  $eng.LoadGrammar($wake)
  try { $dict = New-Object System.Speech.Recognition.DictationGrammar; $dict.Name = 'other'; $dict.Weight = 0.3; $eng.LoadGrammar($dict) } catch { }
  $eng.SetInputToDefaultAudioDevice()
  [Console]::Out.WriteLine('READY:' + $info.Culture.Name)
  while ($true) {
    $r = $eng.Recognize([TimeSpan]::FromSeconds(30))
    if ($r -ne $null -and $r.Grammar.Name -eq 'wake' -and $r.Confidence -ge $Min) {
      [Console]::Out.WriteLine('WAKE:' + [Math]::Round($r.Confidence, 2) + ':' + $r.Text)
    }
  }
} catch {
  [Console]::Out.WriteLine('ERROR:' + $_.Exception.Message)
  exit 1
}
`;

class WakeWord {
  constructor({ dir, onStatus, onHit, log = () => {}, platform = process.platform, spawnImpl = spawn }) {
    Object.assign(this, { dir, onStatus, onHit, log, platform, spawnImpl });
    this.proc = null; this.wanted = false; this.sens = 'mid'; this.restarts = 0; this.state = { state: 'off' };
  }
  status(s) { this.state = s; this.onStatus?.(s); }

  set(enabled, sens = this.sens) {
    const changed = sens !== this.sens;
    this.sens = THRESHOLD[sens] ? sens : 'mid';
    this.wanted = !!enabled;
    if (!this.wanted) return this.stop();
    if (this.platform !== 'win32') return this.status({ state: 'unsupported', detail: '„Hey Jarvis“ gibt es nur unter Windows.' });
    if (this.proc && changed) { this.stop(); }
    if (!this.proc) { this.restarts = 0; this.start(); }
  }

  start() {
    const file = path.join(this.dir, 'jarvis-weckwort.ps1');
    fs.writeFileSync(file, '﻿' + SCRIPT); // BOM, damit Umlaute in PowerShell 5 stimmen
    this.status({ state: 'starting' });
    const proc = this.spawnImpl('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', file, '-Min', String(THRESHOLD[this.sens])], { windowsHide: true });
    this.proc = proc;
    let buf = '';
    let fatal = false;
    proc.stdout.setEncoding('utf8');
    proc.stdout.on('data', (d) => {
      buf += d;
      let i;
      while ((i = buf.indexOf('\n')) !== -1) {
        const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1);
        if (line.startsWith('READY:')) { this.restarts = 0; this.status({ state: 'ready', detail: line.slice(6) }); this.log(`Weckwort bereit (${line.slice(6)})`); }
        else if (line.startsWith('WAKE:')) {
          const [, conf, ...text] = line.split(':');
          this.log(`Weckwort erkannt (${conf})`);
          this.onHit?.({ confidence: Number(conf), text: text.join(':') });
        } else if (line.startsWith('ERROR:')) { fatal = true; this.status({ state: 'error', detail: line.slice(6) }); this.log(`Weckwort-Fehler: ${line.slice(6)}`); }
      }
    });
    proc.stderr?.on('data', (d) => this.log(`Weckwort: ${String(d).trim().slice(0, 200)}`));
    proc.on('error', (err) => { fatal = true; this.status({ state: 'error', detail: `PowerShell nicht startbar: ${err.message}` }); });
    proc.on('exit', () => {
      if (this.proc !== proc) return;
      this.proc = null;
      if (!this.wanted) return;
      if (fatal || this.restarts >= 3) { if (!fatal) this.status({ state: 'error', detail: 'Weckwort-Erkennung ist mehrfach abgestürzt.' }); return; }
      this.restarts++;
      setTimeout(() => { if (this.wanted && !this.proc) this.start(); }, 1500 * this.restarts);
    });
  }

  stop() {
    this.wanted = false;
    const p = this.proc; this.proc = null;
    try { p?.kill(); } catch { /* egal */ }
    this.status({ state: 'off' });
  }
}

module.exports = { WakeWord, THRESHOLD, SCRIPT };
